import{_ as e,o as r,c as t,a2 as o}from"./chunks/framework.Cc8dJFaW.js";const u=JSON.parse('{"title":"2026-11-20 Agent 核心研究与竞品动态","description":"","frontmatter":{"title":"2026-11-20 Agent 核心研究与竞品动态","outline":[2,3]},"headers":[],"relativePath":"zh/runtime/daily-intelligence/2026-11-20.md","filePath":"zh/runtime/daily-intelligence/2026-11-20.md","lastUpdated":null}'),p={name:"zh/runtime/daily-intelligence/2026-11-20.md"};function n(l,a,i,h,s,d){return r(),t("div",null,[...a[0]||(a[0]=[o('<h1 id="_2026-11-20-agent-核心研究与竞品动态" tabindex="-1">2026-11-20 Agent 核心研究与竞品动态 <a class="header-anchor" href="#_2026-11-20-agent-核心研究与竞品动态" aria-label="Permalink to &quot;2026-11-20 Agent 核心研究与竞品动态&quot;">​</a></h1><p>核心结论：MCP Events合入正文已是Final，事件唤醒仍需授权、去重与缺口结算；数字员工交付必须区分任务成功、成果保存和流式结果持久化。已按来源日期和原编号结算昨日七组待办，不能用今天A编号替代。</p><p>实际起点：2026-11-20 11:18:05 Asia/Shanghai。最新main Registry为47人，88个原始仓库入口，接续2026-11-19T024709Z；下文事件日期为UTC。31项外部观察、5组分析，另有7项跨日承接。今日新增实验、文章、正式评审及开发派工均为0。</p><h2 id="跨日未完成项结算" tabindex="-1">跨日未完成项结算 <a class="header-anchor" href="#跨日未完成项结算" aria-label="Permalink to &quot;跨日未完成项结算&quot;">​</a></h2><p>来源均为<a href="./2026-11-19">2026-11-19日报</a>。11月20日补记核对<a href="https://github.com/joinwell52-AI/joinwell52/blob/main/research/manual-runs/2026-11-19-skill-side-effects/00-report.md" target="_blank" rel="noreferrer">昨日独立实验报告</a>与已发布双语文章：<a href="/joinwell52/zh/research/2026-11-19-skill-says-read-only">中文</a>、<a href="/joinwell52/en/research/2026-11-19-skill-says-read-only">English</a>。它们发生在昨日巡检快照之后，不回改旧日报，也不计作今天新实验/文章。没有真实文件写入，没有完整审批或live skill挂载验证。</p><table tabindex="0"><thead><tr><th>来源日期＋原编号</th><th>本轮结算</th><th>范围、待办与依据</th></tr></thead><tbody><tr><td>2026-11-19 A1</td><td>部分完成；继续待办</td><td>11月19日另行完成O1固定版本13项上游测试、6项合成断言；CodeFlowMu schema 3项、动作事实6项。11月20日核对已发布实验报告，今日未重跑。O2—O6、真实技能挂载、完整授权/执行仍待办。</td></tr><tr><td>2026-11-19 A2</td><td>继续待办</td><td>既有schema/操作事实探针不能替代分叉授权、撤销和身份切换实验；本轮只有上游策略刷新新证据。</td></tr><tr><td>2026-11-19 A3</td><td>继续待办</td><td>三岗位派发—消费—独立验收及外部交付实验未执行；新增私有PR身份校验材料用于完善案例。</td></tr><tr><td>2026-11-19 A4</td><td>继续待办</td><td>未本地重放满盘、扫锁、空闲死亡和线程池故障；新恢复/背压修复仅作对照材料。 昨日O27的#9539已关闭未合入，后继#9574仍OPEN。</td></tr><tr><td>2026-11-19 A5</td><td>资料留存；验证待办</td><td>记忆重启、多进程、不同用户预算体验未做；嵌套Flow状态新修复增加隔离对照，不算已验证。</td></tr><tr><td>2026-11-19 A6</td><td>资料核查有进展；实验待办</td><td>完成MCP Events提案及相关消息契约核查；重复、乱序、断线重放实验仍未执行。</td></tr><tr><td>2026-11-19 A7</td><td>继续待办</td><td>未进行完整安装、手机/Windows升级、签名或回滚验收；正式发行不能替代这些体验，Orca许可缺口保留。</td></tr></tbody></table><h2 id="事实观察" tabindex="-1">事实观察 <a class="header-anchor" href="#事实观察" aria-label="Permalink to &quot;事实观察&quot;">​</a></h2><p><span id="o1"></span></p><h3 id="o1-mcp-events-extension-已标为-final-不能沿用早期草案描述" tabindex="-1">O1 MCP Events Extension 已标为 Final，不能沿用早期草案描述 <a class="header-anchor" href="#o1-mcp-events-extension-已标为-final-不能沿用早期草案描述" aria-label="Permalink to &quot;O1 MCP Events Extension 已标为 Final，不能沿用早期草案描述&quot;">​</a></h3><p>11月19日 #3415 已合入，合入正文明确 Status:Final，扩展标识 io.modelcontextprotocol/events；PR早期说明仍含设计草图/0000文件描述，不能代替实际正文。支持按事件类型选择poll、stream、签名webhook，均非必选；cursor恢复、可选replay与truncated丢失提示需分别处理，eventId去重范围是订阅。事件载荷仍是不可信数据，沿用MCP主体授权。Final不等于已核验所有SDK和服务器实现。</p><p>原始证据与状态：<a href="https://github.com/modelcontextprotocol/modelcontextprotocol/pull/3415" target="_blank" rel="noreferrer">MERGED · 2026-11-19T15:06:35Z</a> · <a href="https://github.com/modelcontextprotocol/modelcontextprotocol/blob/8a18b4b3292b9f9b3aee73f6325f9f62f19a89f9/seps/3415-events-extension.md" target="_blank" rel="noreferrer">FINAL_SPEC_TEXT · 2026-11-19</a></p><p><span id="o2"></span></p><h3 id="o2-codex-运行中的线程也必须接受新治理策略" tabindex="-1">O2 Codex：运行中的线程也必须接受新治理策略 <a class="header-anchor" href="#o2-codex-运行中的线程也必须接受新治理策略" aria-label="Permalink to &quot;O2 Codex：运行中的线程也必须接受新治理策略&quot;">​</a></h3><p>11月19日 #62585/#62614 已合入。新策略禁止当前模型时仍应用限制，自动工作排队等待，后续可换合规模型；发布前策略来源变化或线程拒绝更新会报错。配置重载、登录/登出刷新策略，即使其他配置失败仍尝试；迟到低风险分数不能释放更严格的批准要求。</p><p>原始证据与状态：<a href="https://github.com/openai/codex/pull/62585" target="_blank" rel="noreferrer">MERGED · 2026-11-19T20:26:34Z</a> · <a href="https://github.com/openai/codex/pull/62614" target="_blank" rel="noreferrer">MERGED · 2026-11-19T22:32:19Z</a></p><p><span id="o3"></span></p><h3 id="o3-codex-恢复待处理请求有背压-也重新检查审批资格" tabindex="-1">O3 Codex：恢复待处理请求有背压，也重新检查审批资格 <a class="header-anchor" href="#o3-codex-恢复待处理请求有背压-也重新检查审批资格" aria-label="Permalink to &quot;O3 Codex：恢复待处理请求有背压，也重新检查审批资格&quot;">​</a></h3><p>11月19日 #62609 已合入。先响应thread/resume，再后台逐个重放待处理请求，每连接等待写回执；发送前确认请求仍待处理及人工审批资格。再次resume替换旧重放，取消订阅或断线停止，不把恢复当成无条件重发。</p><p>原始证据与状态：<a href="https://github.com/openai/codex/pull/62609" target="_blank" rel="noreferrer">MERGED · 2026-11-19T22:15:58Z</a></p><p><span id="o4"></span></p><h3 id="o4-codex-只有完整持久化的工具结果才能从内存释放" tabindex="-1">O4 Codex：只有完整持久化的工具结果才能从内存释放 <a class="header-anchor" href="#o4-codex-只有完整持久化的工具结果才能从内存释放" aria-label="Permalink to &quot;O4 Codex：只有完整持久化的工具结果才能从内存释放&quot;">​</a></h3><p>11月20日 #62641 已合入。分页线程成功MCP结果只有与存储完整一致才释放活跃turn内存；恢复按item ID读取最新结果，避免旧历史页。截断、缺失、元数据不匹配或失败结果继续保留。对长期运行，降内存与证据可恢复性一起核验。</p><p>原始证据与状态：<a href="https://github.com/openai/codex/pull/62641" target="_blank" rel="noreferrer">MERGED · 2026-11-20T01:49:46Z</a></p><p><span id="o5"></span></p><h3 id="o5-codex-本线程保留与传给子agent分开-排队邮件不必重开完成轮次" tabindex="-1">O5 Codex：本线程保留与传给子Agent分开，排队邮件不必重开完成轮次 <a class="header-anchor" href="#o5-codex-本线程保留与传给子agent分开-排队邮件不必重开完成轮次" aria-label="Permalink to &quot;O5 Codex：本线程保留与传给子Agent分开，排队邮件不必重开完成轮次&quot;">​</a></h3><p>11月20日 #62654/#62639 已合入。alwaysInThread跨上下文保留但不传给子Agent；alwaysInChildren控制继承，always兼顾两者，工具调用与输出需相邻且同策略。已有最终答复时，queue-only邮件留待下一轮；用户steering仍能重开。上下文继承不能据此推导授权继承。</p><p>原始证据与状态：<a href="https://github.com/openai/codex/pull/62654" target="_blank" rel="noreferrer">MERGED · 2026-11-20T03:00:31Z</a> · <a href="https://github.com/openai/codex/pull/62639" target="_blank" rel="noreferrer">MERGED · 2026-11-20T01:36:08Z</a></p><p><span id="o6"></span></p><h3 id="o6-codex-并发执行状态更新不再覆盖已有退出证据" tabindex="-1">O6 Codex：并发执行状态更新不再覆盖已有退出证据 <a class="header-anchor" href="#o6-codex-并发执行状态更新不再覆盖已有退出证据" aria-label="Permalink to &quot;O6 Codex：并发执行状态更新不再覆盖已有退出证据&quot;">​</a></h3><p>11月19日 #62557 已合入。生命周期转换在写锁内原位更新；拒绝stdin写入或后续终止不再用旧快照覆盖退出码、沙箱拒绝和首个失败原因。它是终态证据一致性修复，不代表所有进程已被验证停止。</p><p>原始证据与状态：<a href="https://github.com/openai/codex/pull/62557" target="_blank" rel="noreferrer">MERGED · 2026-11-19T17:34:01Z</a></p><p><span id="o7"></span></p><h3 id="o7-codex-子agent遥测区分接受停止与运行结果" tabindex="-1">O7 Codex：子Agent遥测区分接受停止与运行结果 <a class="header-anchor" href="#o7-codex-子agent遥测区分接受停止与运行结果" aria-label="Permalink to &quot;O7 Codex：子Agent遥测区分接受停止与运行结果&quot;">​</a></h3><p>11月19日 #62567 已合入。记录spawn、接受close/interrupt以及初始/后续/恢复turn尝试，每次尝试最多一个结果；使用thread/turn/call ID关联，ID不作指标标签。已接受停止即使目标空闲也计数，因此该计数不能当退出证明。</p><p>原始证据与状态：<a href="https://github.com/openai/codex/pull/62567" target="_blank" rel="noreferrer">MERGED · 2026-11-19T18:40:07Z</a></p><p><span id="o8"></span></p><h3 id="o8-codex-0-171正式发行-源码新能力不自动算入安装包" tabindex="-1">O8 Codex 0.171正式发行，源码新能力不自动算入安装包 <a class="header-anchor" href="#o8-codex-0-171正式发行-源码新能力不自动算入安装包" aria-label="Permalink to &quot;O8 Codex 0.171正式发行，源码新能力不自动算入安装包&quot;">​</a></h3><p>本轮正式发布rust-v0.171.0，包括非交互exec --remote、子会话轨迹和恢复等此前合入成果。只计新增发行状态，不把历史修复重复算当天代码变化；本轮后续策略、内存和保留机制是否已打包需按发行范围核验。</p><p>原始证据与状态：<a href="https://github.com/openai/codex/releases/tag/rust-v0.171.0" target="_blank" rel="noreferrer">RELEASED · 2026-11-20T00:44:47Z</a></p><p><span id="o9"></span></p><h3 id="o9-paperclip-pr合入验收使用该运行当前获准的身份" tabindex="-1">O9 Paperclip：PR合入验收使用该运行当前获准的身份 <a class="header-anchor" href="#o9-paperclip-pr合入验收使用该运行当前获准的身份" aria-label="Permalink to &quot;O9 Paperclip：PR合入验收使用该运行当前获准的身份&quot;">​</a></h3><p>11月19日 #22357 已合入，补昨日O28。原后台凭证读不到能合并私有PR的managed身份，导致已交付仍拒绝完成；现在按公司/任务/运行及当前grant、成员、trust边界解析身份，成功运行复核也受锁和steering结算约束。GitHub仍须独立确认合入，不能只信工件元数据。学习及交付治理竞争关注高，主雷达不变。</p><p>原始证据与状态：<a href="https://github.com/paperclipai/paperclip/pull/22357" target="_blank" rel="noreferrer">MERGED · 2026-11-19T22:44:04Z</a></p><p><span id="o10"></span></p><h3 id="o10-paperclip-未知执行结果的hold不能被agent改状态绕过" tabindex="-1">O10 Paperclip：未知执行结果的hold不能被Agent改状态绕过 <a class="header-anchor" href="#o10-paperclip-未知执行结果的hold不能被agent改状态绕过" aria-label="Permalink to &quot;O10 Paperclip：未知执行结果的hold不能被Agent改状态绕过&quot;">​</a></h3><p>11月19日 #22245 已合入。Agent对执行hold任务的改状态、reopen/resume/checkout等请求不能把它移出Blocked，返回409及解除所需动作。此前列表显示可工作而准入持续拒绝，导致调度反复空转。学习价值高，任务展示与真实准入一致性需一起看。</p><p>原始证据与状态：<a href="https://github.com/paperclipai/paperclip/pull/22245" target="_blank" rel="noreferrer">MERGED · 2026-11-19T20:37:58Z</a></p><p><span id="o11"></span></p><h3 id="o11-paperclip-重启恢复也协商下一运行身份" tabindex="-1">O11 Paperclip：重启恢复也协商下一运行身份 <a class="header-anchor" href="#o11-paperclip-重启恢复也协商下一运行身份" aria-label="Permalink to &quot;O11 Paperclip：重启恢复也协商下一运行身份&quot;">​</a></h3><p>11月19日 #22343 已合入。provider声明resumeIdentityVersion:1时，Core重启恢复已释放的warm task也直接以新run启动，不再先用旧run再交接。能力协商有条件，不能外推所有provider都支持；学习价值高，主雷达继续关注授权与恢复边界。</p><p>原始证据与状态：<a href="https://github.com/paperclipai/paperclip/pull/22343" target="_blank" rel="noreferrer">MERGED · 2026-11-19T19:20:49Z</a></p><p><span id="o12"></span></p><h3 id="o12-paperclip-在线迁移必须实际推动日志与轨迹保存" tabindex="-1">O12 Paperclip：在线迁移必须实际推动日志与轨迹保存 <a class="header-anchor" href="#o12-paperclip-在线迁移必须实际推动日志与轨迹保存" aria-label="Permalink to &quot;O12 Paperclip：在线迁移必须实际推动日志与轨迹保存&quot;">​</a></h3><p>11月19日 #22337 已合入。准备阶段通过有预算分页推进log/provider trace，用独立cursor、共享owner及owner_busy标识，取消后仍跟踪底层传输直到结算；无法证明canonical coverage或有活跃写入仍阻断。学习价值高，不能仅凭曾有后台扫描就删本地卷。</p><p>原始证据与状态：<a href="https://github.com/paperclipai/paperclip/pull/22337" target="_blank" rel="noreferrer">MERGED · 2026-11-19T18:28:06Z</a></p><p><span id="o13"></span></p><h3 id="o13-paperclip-重试审计写入-不重放真实连接器动作" tabindex="-1">O13 Paperclip：重试审计写入，不重放真实连接器动作 <a class="header-anchor" href="#o13-paperclip-重试审计写入-不重放真实连接器动作" aria-label="Permalink to &quot;O13 Paperclip：重试审计写入，不重放真实连接器动作&quot;">​</a></h3><p>11月19日 #22329 已合入。仅对审计insert遇到三类锁竞争做最多5次有界重试，其他错误仍失败。死锁受害写入本身回滚，重试不应重复审计行；作用范围不是重发整个工具调用。上游有真实数据库死锁回归，本轮未复现。学习价值高，恢复竞争关注提高。</p><p>原始证据与状态：<a href="https://github.com/paperclipai/paperclip/pull/22329" target="_blank" rel="noreferrer">MERGED · 2026-11-19T18:23:22Z</a></p><p><span id="o14"></span></p><h3 id="o14-paperclip-数字员工可调整所属人的职责和例程-并可撤销" tabindex="-1">O14 Paperclip：数字员工可调整所属人的职责和例程，并可撤销 <a class="header-anchor" href="#o14-paperclip-数字员工可调整所属人的职责和例程-并可撤销" aria-label="Permalink to &quot;O14 Paperclip：数字员工可调整所属人的职责和例程，并可撤销&quot;">​</a></h3><p>11月19日 #22261/#22274 已合入。实验性responsibilities下，Agent可替其负责的人修改职责/领域及例程，变更留版本可撤销，永久删除仍需确认卡；职责与routine需按运行负责用户核权。学习价值高，数字员工产品竞争关注提高，主雷达不变；未体验真实组织协作。</p><p>原始证据与状态：<a href="https://github.com/paperclipai/paperclip/pull/22261" target="_blank" rel="noreferrer">MERGED · 2026-11-19T15:29:12Z</a> · <a href="https://github.com/paperclipai/paperclip/pull/22274" target="_blank" rel="noreferrer">MERGED · 2026-11-19T15:30:04Z</a></p><p><span id="o15"></span></p><h3 id="o15-paperclip-缩小目录读取也要保留决定授权的工具名字" tabindex="-1">O15 Paperclip：缩小目录读取也要保留决定授权的工具名字 <a class="header-anchor" href="#o15-paperclip-缩小目录读取也要保留决定授权的工具名字" aria-label="Permalink to &quot;O15 Paperclip：缩小目录读取也要保留决定授权的工具名字&quot;">​</a></h3><p>11月19日 #22356 已合入。只读standing-instruction候选连接的目录，但同一短连接ID的命名peer仍进快照，命名后再过滤；避免优化改变工具名及策略命中。学习价值高，权限相关名字不能由读取范围偶然决定；既有grant/trust不变。</p><p>原始证据与状态：<a href="https://github.com/paperclipai/paperclip/pull/22356" target="_blank" rel="noreferrer">MERGED · 2026-11-19T22:07:48Z</a></p><p><span id="o16"></span></p><h3 id="o16-orca-手机协调者可回答worker许可请求" tabindex="-1">O16 Orca：手机协调者可回答worker许可请求 <a class="header-anchor" href="#o16-orca-手机协调者可回答worker许可请求" aria-label="Permalink to &quot;O16 Orca：手机协调者可回答worker许可请求&quot;">​</a></h3><p>11月20日 #44942 已合入。结构化手机聊天在自己没有待答问题时显示最旧worker许可，仅宿主声明paired-worker-approvals.v1时订阅；回答走带契约版本的approvalAnswer，断流重订阅。学习/移动治理竞争关注高，第二圈不变；源码合入不等于手机实机已验收。</p><p>原始证据与状态：<a href="https://github.com/stablyai/orca/pull/44942" target="_blank" rel="noreferrer">MERGED · 2026-11-20T03:10:00Z</a></p><p><span id="o17"></span></p><h3 id="o17-orca-bots正式版-工具与身份分发扩展到更多托管会话" tabindex="-1">O17 Orca Bots正式版：工具与身份分发扩展到更多托管会话 <a class="header-anchor" href="#o17-orca-bots正式版-工具与身份分发扩展到更多托管会话" aria-label="Permalink to &quot;O17 Orca Bots正式版：工具与身份分发扩展到更多托管会话&quot;">​</a></h3><p>v1.4.265本轮正式发布，上游说明更多托管Agent会话获得工具与身份、可代表owner分享、Gmail触发匹配真实发送地址。自动更新默认关闭，有活跃终端等条件时等待；手机兼容受安装版本边界约束。学习价值高，数字员工竞争关注提高但第二圈不变；未独立验证整套权限或商业/许可边界。</p><p>原始证据与状态：<a href="https://github.com/stablyai/orca/releases/tag/v1.4.265" target="_blank" rel="noreferrer">RELEASED · 2026-11-19T23:41:51Z</a></p><p><span id="o18"></span></p><h3 id="o18-orca-重打包的linux安装不交给dpkg更新" tabindex="-1">O18 Orca：重打包的Linux安装不交给dpkg更新 <a class="header-anchor" href="#o18-orca-重打包的linux安装不交给dpkg更新" aria-label="Permalink to &quot;O18 Orca：重打包的Linux安装不交给dpkg更新&quot;">​</a></h3><p>11月20日 #45067 已合入。deb自更新除工具存在外，还要求dpkg的orca-ide安装清单存在；重打包到其他发行版时转为系统包管理提示，避免覆盖其他包管理器文件。学习价值中高，交付专项观察；不是完整签名或回滚验收。</p><p>原始证据与状态：<a href="https://github.com/stablyai/orca/pull/45067" target="_blank" rel="noreferrer">MERGED · 2026-11-20T02:29:58Z</a></p><p><span id="o19"></span></p><h3 id="o19-crewai-版本化成果文件正式交付-但保存失败不会阻断run" tabindex="-1">O19 CrewAI：版本化成果文件正式交付，但保存失败不会阻断run <a class="header-anchor" href="#o19-crewai-版本化成果文件正式交付-但保存失败不会阻断run" aria-label="Permalink to &quot;O19 CrewAI：版本化成果文件正式交付，但保存失败不会阻断run&quot;">​</a></h3><p>11月19日 #9551合入并进入1.15.44。成果有identifier、逐版本文件、上传前UUID及创建事件；并发保存不覆盖，回调可读成果链接。保存失败只警告，不失败整个run；文件结果与任务成功需分别验收。学习价值高，是CodeFlowMu成果契约对照，不能因此认定交付已可靠完成。</p><p>原始证据与状态：<a href="https://github.com/crewAIInc/crewAI/pull/9551" target="_blank" rel="noreferrer">MERGED · 2026-11-19T13:10:09Z</a> · <a href="https://github.com/crewAIInc/crewAI/releases/tag/1.15.44" target="_blank" rel="noreferrer">RELEASED · 2026-11-19T17:59:49Z</a></p><p><span id="o20"></span></p><h3 id="o20-crewai-嵌套默认状态改深拷贝-失败回退仍需留意" tabindex="-1">O20 CrewAI：嵌套默认状态改深拷贝，失败回退仍需留意 <a class="header-anchor" href="#o20-crewai-嵌套默认状态改深拷贝-失败回退仍需留意" aria-label="Permalink to &quot;O20 CrewAI：嵌套默认状态改深拷贝，失败回退仍需留意&quot;">​</a></h3><p>11月19日 #9527 已合入并发行。修复dict浅拷贝让不同Flow共享嵌套容器；无法deep-copy时仍回退dict()，因此不能宣称所有自定义对象都隔离。延续昨日运行ID问题，身份与状态值隔离是两项检查。</p><p>原始证据与状态：<a href="https://github.com/crewAIInc/crewAI/pull/9527" target="_blank" rel="noreferrer">MERGED · 2026-11-19T13:32:49Z</a> · <a href="https://github.com/crewAIInc/crewAI/releases/tag/1.15.44" target="_blank" rel="noreferrer">RELEASED · 2026-11-19T17:59:49Z</a></p><p><span id="o21"></span></p><h3 id="o21-crewai-文件路径修复有明确的未覆盖范围" tabindex="-1">O21 CrewAI：文件路径修复有明确的未覆盖范围 <a class="header-anchor" href="#o21-crewai-文件路径修复有明确的未覆盖范围" aria-label="Permalink to &quot;O21 CrewAI：文件路径修复有明确的未覆盖范围&quot;">​</a></h3><p>11月19日 #9569 已合入，处理父目录symlink及字符串前缀检查绕过，实际解析后用路径包含关系。无symlink的外部绝对路径仍允许，这是已声明兼容边界；不能写成所有文件均被限制在cwd。</p><p>原始证据与状态：<a href="https://github.com/crewAIInc/crewAI/pull/9569" target="_blank" rel="noreferrer">MERGED · 2026-11-19T06:08:20Z</a></p><p><span id="o22"></span></p><h3 id="o22-crewai-昨日超时提案关闭未合入-后继仍开放" tabindex="-1">O22 CrewAI：昨日超时提案关闭未合入，后继仍开放 <a class="header-anchor" href="#o22-crewai-昨日超时提案关闭未合入-后继仍开放" aria-label="Permalink to &quot;O22 CrewAI：昨日超时提案关闭未合入，后继仍开放&quot;">​</a></h3><p>更新2026-11-19 O27：#9539于11月19日关闭未合入，因artifacts等改动冲突，由#9574重建。后者当前OPEN，涵盖kickoff、kickoff_async、akickoff；作者仍注明本地测试未运行。不能把关闭当修复完成，也不能称1.15.44已交付这项能力。</p><p>原始证据与状态：<a href="https://github.com/crewAIInc/crewAI/pull/9539" target="_blank" rel="noreferrer">CLOSED_UNMERGED · 2026-11-19T16:03:34Z</a> · <a href="https://github.com/crewAIInc/crewAI/pull/9574" target="_blank" rel="noreferrer">OPEN · 2026-11-19T16:03:29Z</a></p><p><span id="o23"></span></p><h3 id="o23-langgraph-send分派工具与边路径读取同一类型状态" tabindex="-1">O23 LangGraph：Send分派工具与边路径读取同一类型状态 <a class="header-anchor" href="#o23-langgraph-send分派工具与边路径读取同一类型状态" aria-label="Permalink to &quot;O23 LangGraph：Send分派工具与边路径读取同一类型状态&quot;">​</a></h3><p>11月19日 #9728 已合入。裸工具列表Send原来给工具原始dict，而边路径可给Pydantic/dataclass；现在按图schema读取/强制转换，包含managed values。与昨日wrapper覆盖问题不同，这是分派路径差异；未做本地回归。</p><p>原始证据与状态：<a href="https://github.com/langchain-ai/langgraph/pull/9728" target="_blank" rel="noreferrer">MERGED · 2026-11-19T04:55:30Z</a></p><p><span id="o24"></span></p><h3 id="o24-langgraph-清空消息和空checkpoint的重放语义修正" tabindex="-1">O24 LangGraph：清空消息和空checkpoint的重放语义修正 <a class="header-anchor" href="#o24-langgraph-清空消息和空checkpoint的重放语义修正" aria-label="Permalink to &quot;O24 LangGraph：清空消息和空checkpoint的重放语义修正&quot;">​</a></h3><p>11月19日 #9735 已合入。REMOVE_ALL_MESSAGES清除状态及本批此前写入；None checkpoint按空通道恢复，避免给reducer传None崩溃。下游统一reducer可改善稳定消息ID，但不能据此证明所有下游已迁移。</p><p>原始证据与状态：<a href="https://github.com/langchain-ai/langgraph/pull/9735" target="_blank" rel="noreferrer">MERGED · 2026-11-19T23:08:18Z</a></p><p><span id="o25"></span></p><h3 id="o25-langchain-并行流式工具参数按item-id补齐" tabindex="-1">O25 LangChain：并行流式工具参数按item ID补齐 <a class="header-anchor" href="#o25-langchain-并行流式工具参数按item-id补齐" aria-label="Permalink to &quot;O25 LangChain：并行流式工具参数按item ID补齐&quot;">​</a></h3><p>11月19日 #41963 已合入并进入langchain-openai 1.8.5。从done/最终快照只补缺少的参数后缀，避免并行参数串线、空参数和重复拼接。动作前授权应针对最终实际参数，而非不完整delta；本轮未调用真实模型复现。</p><p>原始证据与状态：<a href="https://github.com/langchain-ai/langchain/pull/41963" target="_blank" rel="noreferrer">MERGED · 2026-11-19T23:01:03Z</a> · <a href="https://github.com/langchain-ai/langchain/releases/tag/langchain-openai%3D%3D1.8.5" target="_blank" rel="noreferrer">RELEASED · 2026-11-19T23:16:20Z</a></p><p><span id="o26"></span></p><h3 id="o26-github-mcp-pr资源路径补全使用pr-head" tabindex="-1">O26 GitHub MCP：PR资源路径补全使用PR head <a class="header-anchor" href="#o26-github-mcp-pr资源路径补全使用pr-head" aria-label="Permalink to &quot;O26 GitHub MCP：PR资源路径补全使用PR head&quot;">​</a></h3><p>11月19日 #3860 已合入。refs/pull/.../head资源不再用默认分支补全路径，避免漏新文件、建议已删文件；非法PR号在API请求前拒绝。值得对照工件读取的版本一致性，合入不自动等于正式服务器版本更新。</p><p>原始证据与状态：<a href="https://github.com/github/github-mcp-server/pull/3860" target="_blank" rel="noreferrer">MERGED · 2026-11-19T18:44:50Z</a></p><p><span id="o27"></span></p><h3 id="o27-langfuse-角色迁移先修复并约束授权数据漂移" tabindex="-1">O27 Langfuse：角色迁移先修复并约束授权数据漂移 <a class="header-anchor" href="#o27-langfuse-角色迁移先修复并约束授权数据漂移" aria-label="Permalink to &quot;O27 Langfuse：角色迁移先修复并约束授权数据漂移&quot;">​</a></h3><p>11月19日 #20234 已合入。迁移修复角色分配与membership不同步、孤立分配及跨组织项目membership，用延迟约束和漂移查询防复发，保留带标签/到期的特殊授权。后续才改按assignment授权，不能写成本次已完成整个RBAC切换。</p><p>原始证据与状态：<a href="https://github.com/langfuse/langfuse/pull/20234" target="_blank" rel="noreferrer">MERGED · 2026-11-19T18:21:25Z</a></p><p><span id="o28"></span></p><h3 id="o28-openhands-孤立工具消息需进入畸形历史恢复路径" tabindex="-1">O28 OpenHands：孤立工具消息需进入畸形历史恢复路径 <a class="header-anchor" href="#o28-openhands-孤立工具消息需进入畸形历史恢复路径" aria-label="Permalink to &quot;O28 OpenHands：孤立工具消息需进入畸形历史恢复路径&quot;">​</a></h3><p>11月20日 #6678 已合入。将无对应调用、重复ID、错序结果等提供方错误文本识别为LLMMalformedConversationHistoryError，进入既有condensation恢复，而非泛化bad request。它改错误分类，不证明压缩已保留每项授权和副作用证据。</p><p>原始证据与状态：<a href="https://github.com/OpenHands/software-agent-sdk/pull/6678" target="_blank" rel="noreferrer">MERGED · 2026-11-20T01:16:29Z</a></p><p><span id="o29"></span></p><h3 id="o29-openhands-sdk-1-63正式发行-实验性开关与源码边界分别核验" tabindex="-1">O29 OpenHands SDK 1.63正式发行，实验性开关与源码边界分别核验 <a class="header-anchor" href="#o29-openhands-sdk-1-63正式发行-实验性开关与源码边界分别核验" aria-label="Permalink to &quot;O29 OpenHands SDK 1.63正式发行，实验性开关与源码边界分别核验&quot;">​</a></h3><p>本轮v1.63.0正式发行，包含用户可切换的实验功能框架、会话reactions和客户端接入等历史成果。新增发行是交付事实；不能把更晚的源码修复或尚无调用者的judge自动说成已在产品生效。未安装验收。</p><p>原始证据与状态：<a href="https://github.com/OpenHands/software-agent-sdk/releases/tag/v1.63.0" target="_blank" rel="noreferrer">RELEASED · 2026-11-19T19:07:57Z</a></p><p><span id="o30"></span></p><h3 id="o30-ag2-1-3-3-sdk升级改变api版本与http客户端默认值" tabindex="-1">O30 AG2 1.3.3：SDK升级改变API版本与HTTP客户端默认值 <a class="header-anchor" href="#o30-ag2-1-3-3-sdk升级改变api版本与http客户端默认值" aria-label="Permalink to &quot;O30 AG2 1.3.3：SDK升级改变API版本与HTTP客户端默认值&quot;">​</a></h3><p>v1.3.3正式发行，允许google-genai 3.x；Developer API默认从v1beta变v1，部分latest/preview需显式版本。HTTP默认改httpx2，显式客户端配置需按新版核对。模型生成API相似不等于接入兼容无需检查；未本地升级。</p><p>原始证据与状态：<a href="https://github.com/ag2ai/ag2/releases/tag/v1.3.3" target="_blank" rel="noreferrer">RELEASED · 2026-11-19T20:30:48Z</a></p><p><span id="o31"></span></p><h3 id="o31-adk-撤回缺last-chunk时的聚合持久化-重复与缺失需同时检查" tabindex="-1">O31 ADK：撤回缺last_chunk时的聚合持久化，重复与缺失需同时检查 <a class="header-anchor" href="#o31-adk-撤回缺last-chunk时的聚合持久化-重复与缺失需同时检查" aria-label="Permalink to &quot;O31 ADK：撤回缺last_chunk时的聚合持久化，重复与缺失需同时检查&quot;">​</a></h3><p>本轮提交撤回RemoteA2aAgent在流结束后再发聚合事件的做法，因为同时转发partial与聚合的客户端会重复显示回答。撤回后，没有last_chunk闭合的流答案再次不持久化；计划以设置重引入尚未完成。应同时检查显示去重和会话保存，不能把一端修好当完整交付。</p><p>原始证据与状态：<a href="https://github.com/google/adk-python/commit/5523aa7333d36736262b2e38d7a302f1505b1822" target="_blank" rel="noreferrer">COMMITTED · 2026-11-19T19:04:14Z</a></p><h2 id="研究分析" tabindex="-1">研究分析 <a class="header-anchor" href="#研究分析" aria-label="Permalink to &quot;研究分析&quot;">​</a></h2><p><span id="a1"></span></p><h3 id="a1-事件唤醒有了正式语义-但还需要任务授权和缺口处理" tabindex="-1">A1 事件唤醒有了正式语义，但还需要任务授权和缺口处理 <a class="header-anchor" href="#a1-事件唤醒有了正式语义-但还需要任务授权和缺口处理" aria-label="Permalink to &quot;A1 事件唤醒有了正式语义，但还需要任务授权和缺口处理&quot;">​</a></h3><p><a href="#o1">O1</a> · <a href="#o16">O16</a> · <a href="#o25">O25</a> · <a href="#o26">O26</a> · <a href="#o31">O31</a></p><p>已有证据：MCP Events正文为Final，定义事件、订阅、cursor、可选replay与缺口；Orca手机侧按宿主能力订阅并回答。待验证：SDK、事件源和本地适配层能否一致实现。承接2026-11-19 A6，实验仍待办：重放断线、重复、乱序、同一事件命中多个订阅，分别核验订阅去重和任务准入；不可跨订阅误删。事件载荷不自动成为指令或授权。FCoP比较任务/工件/证据契约，事件传输是互补接入层。代价为游标、补偿与状态持久化。互动切入点：truncated出现后，宿主能否证明哪些任务需要补查？</p><p><span id="a2"></span></p><h3 id="a2-持续履职要持续刷新授权-也要限制可撤销的岗位变更" tabindex="-1">A2 持续履职要持续刷新授权，也要限制可撤销的岗位变更 <a class="header-anchor" href="#a2-持续履职要持续刷新授权-也要限制可撤销的岗位变更" aria-label="Permalink to &quot;A2 持续履职要持续刷新授权，也要限制可撤销的岗位变更&quot;">​</a></h3><p><a href="#o2">O2</a> · <a href="#o9">O9</a> · <a href="#o10">O10</a> · <a href="#o14">O14</a> · <a href="#o15">O15</a> · <a href="#o16">O16</a> · <a href="#o17">O17</a> · <a href="#o21">O21</a> · <a href="#o27">O27</a></p><p>已有证据：策略刷新会阻断旧模型，私有PR验收要用当前managed身份，执行hold限制状态变更，职责/例程修改有负责用户及撤销边界。承接2026-11-19 A2：撤销、分叉与身份切换实验继续待办；昨日事实分类探针不能替代这些授权验证。候选加入长任务中途收紧策略、批准后换身份、跨用户改例程，核对动作前后的同一主体和版本。CodeFlowMu可比岗位/SOP与动作控制；FCoP不直接承担所有账号、凭证与调度。学习价值高，企业数字员工竞争关注提高，未据此确认本地缺陷。成本为版本与授权查询、人工接管。</p><p><span id="a3"></span></p><h3 id="a3-交付成功需要独立证据-任务成功或停止计数都不够" tabindex="-1">A3 交付成功需要独立证据，任务成功或停止计数都不够 <a class="header-anchor" href="#a3-交付成功需要独立证据-任务成功或停止计数都不够" aria-label="Permalink to &quot;A3 交付成功需要独立证据，任务成功或停止计数都不够&quot;">​</a></h3><p><a href="#o4">O4</a> · <a href="#o6">O6</a> · <a href="#o7">O7</a> · <a href="#o9">O9</a> · <a href="#o12">O12</a> · <a href="#o13">O13</a> · <a href="#o19">O19</a> · <a href="#o22">O22</a> · <a href="#o23">O23</a> · <a href="#o24">O24</a> · <a href="#o25">O25</a> · <a href="#o26">O26</a> · <a href="#o28">O28</a> · <a href="#o31">O31</a></p><p>已有证据：CrewAI成果保存失败只告警，Paperclip则要求外部PR证据；ADK为去重撤回聚合后又有未闭合流不持久化边界。承接2026-11-19 A3：三岗位派发—消费—验收实验未做。候选用上传失败、缺last_chunk、交错工具参数、私有PR权限失效与重复审计写入，对照任务终态、成果版本、接收/保存回执和验收结论。审计写入重试与工具动作重放必须区分。FCoP比较成果身份和验收证据，执行器结算归Runtime。代价为真实存储/权限故障桩和独立正反对照。互动：run成功但artifact不存在时，产品应向谁展示什么状态？</p><p><span id="a4"></span></p><h3 id="a4-恢复与内存优化以可重建证据为前提" tabindex="-1">A4 恢复与内存优化以可重建证据为前提 <a class="header-anchor" href="#a4-恢复与内存优化以可重建证据为前提" aria-label="Permalink to &quot;A4 恢复与内存优化以可重建证据为前提&quot;">​</a></h3><p><a href="#o3">O3</a> · <a href="#o4">O4</a> · <a href="#o5">O5</a> · <a href="#o6">O6</a> · <a href="#o8">O8</a> · <a href="#o10">O10</a> · <a href="#o11">O11</a> · <a href="#o12">O12</a> · <a href="#o18">O18</a> · <a href="#o20">O20</a> · <a href="#o22">O22</a> · <a href="#o24">O24</a> · <a href="#o28">O28</a> · <a href="#o29">O29</a> · <a href="#o30">O30</a></p><p>已有证据：Codex只释放完整可恢复结果，重放逐条等待回执，进程状态原位更新；Paperclip重启继承新run身份、迁移证据保留owner。承接2026-11-19 A4/A5：恢复故障和记忆/预算体验继续待办；新增测试议题不是已执行结果。候选检查截断存储、旧历史页、慢客户端、取消传输未结算、浅拷贝回退及SDK默认版本变化。停止被接受不能当资源已退出，超时提案关闭未合入也不能当修复。FCoP对照恢复回执，内存、线程、租约和安装迁移归Runtime/产品。代价为故障注入与跨版本环境。</p><p><span id="a5"></span></p><h3 id="a5-跨日处置-先结算技能实验-再推进授权与交付验证" tabindex="-1">A5 跨日处置：先结算技能实验，再推进授权与交付验证 <a class="header-anchor" href="#a5-跨日处置-先结算技能实验-再推进授权与交付验证" aria-label="Permalink to &quot;A5 跨日处置：先结算技能实验，再推进授权与交付验证&quot;">​</a></h3><p><a href="#o1">O1</a> · <a href="#o9">O9</a> · <a href="#o14">O14</a> · <a href="#o16">O16</a> · <a href="#o17">O17</a> · <a href="#o18">O18</a> · <a href="#o19">O19</a> · <a href="#o20">O20</a> · <a href="#o21">O21</a> · <a href="#o22">O22</a> · <a href="#o29">O29</a> · <a href="#o30">O30</a></p><p>2026-11-19 A1的O1已在昨日独立实验并形成双语文章，今日仅核对归档，不新增实验计数；O2—O6和live skill仍未完成。A2/A3/A4仍是下一阶段实验候选，A5资料验证、A6重放、A7完整应用体验均保留，未放弃也未冒充结案。Paperclip身份/职责/恢复学习价值高，主雷达关注提高；Orca手机许可和Bots交付提高第二圈关注；CrewAI提供成果保存语义的框架对照。发行、源码、实验开关和实机验收分别判断，本轮未安装应用、未重审完整商业许可。实验、文章及正式评审/开发派工今天均为0。</p><h2 id="分类、跨项目共振与双源覆盖" tabindex="-1">分类、跨项目共振与双源覆盖 <a class="header-anchor" href="#分类、跨项目共振与双源覆盖" aria-label="Permalink to &quot;分类、跨项目共振与双源覆盖&quot;">​</a></h2><p>本轮沿“事件→主体授权→实际执行→成果/证据→验收”比较机制，不将Runtime、调度、身份或存储直接推成FCoP内核需求。新议题是待验证线索；昨日局部技能实验完成不代表所有旧项结案。今日没有重跑实验、没有新增文章或开发评审、没有外部评论。CodeFlowMu关联未获相称验证时不报已确认缺陷。</p><p>GitHub按88个原始入口核查commit、Issues/PR和Release，并补读分页、入选PR、MCP合入正文及昨日实验报告。264个来源/类型项中228个完整、33个分页未完、TSA三个接口404；只有完整项推进基线。原Superset迁移继续核对同一仓库ID并跟随ParadevAI/Paradev，没有替换Registry，历史缺口仍保留。Codex等大页Release失败后小页成功，覆盖仍按实际分页记录。</p><p>第二类来源实际打开GitHub changelog、Cursor changelog、MCP官方博客，并作选定官方/作者检索；未找到本轮可另列的新公告不等于穷尽社交。MCP正文Final由GitHub原始版本支撑，不能把两个GitHub链接当两种来源。47人的全部X/回复、论文与Discussion、完整安装及License/商业边界未全量核查；昨日作者主页与Orca许可缺口没有被本轮静默清除。六位治理研究者关系保留，Mansura项目不称AGENTSAFE官方Artifact，中文始终使用赵越。</p><p>日档仅修改中英文当日文件和两个索引；不改research/runtime/**、业务生命周期、入口组件或原布局。源文件通过GitHub工具写入并回读，构建发布与中英主页实际点击验收另存本地回执，未提前宣称上线成功。</p>',157)])])}const f=e(p,[["render",n]]);export{u as __pageData,f as default};
